// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IGradientMarketMakerPool
 * @notice Interface for the GradientMarketMakerPool contract with epoch-based pools
 */
interface IGradientMarketMakerPool {
    // Structs for ETH Pool
    struct ETHPoolInfo {
        uint256 accountedEth;
        uint256 totalETH;
        uint256 totalLPShares;
        uint256 accRewardPerShare;
        uint256 rewardBalance;
        uint256 accTokenRewardPerShare; // For token rewards to ETH providers
        uint256 tokenRewardBalance; // Token rewards for ETH providers
        address uniswapPair;
        bool finalized; // Flag to indicate if epoch is finalized
    }

    struct ETHProvider {
        uint256 ethAmount;
        uint256 lpShares;
        uint256 rewardDebt;
        uint256 pendingReward;
        uint256 tokenRewardDebt; // For token rewards
        uint256 pendingTokenReward; // Pending token rewards
    }

    // Structs for Token Pool
    struct TokenPoolInfo {
        uint256 accountedToken;
        uint256 totalTokens;
        uint256 totalLPShares;
        uint256 accRewardPerShare;
        uint256 rewardBalance;
        uint256 accETHRewardPerShare; // For ETH rewards to token providers
        uint256 ethRewardBalance; // ETH rewards for token providers
        address uniswapPair;
        bool finalized; // Flag to indicate if epoch is finalized
    }

    struct TokenProvider {
        uint256 tokenAmount;
        uint256 lpShares;
        uint256 rewardDebt;
        uint256 pendingReward;
        uint256 ethRewardDebt; // For ETH rewards
        uint256 pendingETHReward; // Pending ETH rewards
    }

    // Events
    event ETHLiquidityDeposited(
        address indexed user,
        address token,
        uint256 ethAmount,
        uint256 lpSharesMinted
    );

    event TokenLiquidityDeposited(
        address indexed user,
        address token,
        uint256 tokenAmount,
        uint256 lpSharesMinted
    );

    event ETHLiquidityWithdrawn(
        address indexed user,
        address token,
        uint256 epoch,
        uint256 ethAmount,
        uint256 lpSharesBurned
    );

    event TokenLiquidityWithdrawn(
        address indexed user,
        address token,
        uint256 epoch,
        uint256 tokenAmount,
        uint256 lpSharesBurned
    );

    event PoolFeeDistributed(
        address indexed from,
        uint256 amount,
        address token,
        uint256 epoch,
        bool isETH
    );

    event FeeClaimedFromEthPool(
        address indexed user,
        uint256 amount,
        address token,
        uint256 epoch
    );

    event EthFeeClaimedFromTokenPool(
        address indexed user,
        uint256 amount,
        address token,
        uint256 epoch
    );

    event PoolSharesClaimed(
        address indexed user,
        uint256 amount,
        address token,
        uint256 epoch,
        bool isETH
    );

    event PoolBalanceUpdated(
        address indexed token,
        uint256 newTotalEth,
        uint256 newTotalTokens,
        uint256 newTotalETHLPShares,
        uint256 newTotalTokenLPShares,
        uint256 epoch
    );

    event MinLiquidityUpdated(uint256 newMinLiquidity);
    event MinTokenLiquidityUpdated(uint256 newMinTokenLiquidity);
    event ExcessiveFundsWithdrawn(
        address indexed owner,
        address indexed token,
        uint256 amount,
        string reason
    );

    event EpochIncremented(address indexed token, uint256 newEpoch);

    event RegistryUpdated(address oldRegistry, address newRegistry);

    event EpochCooldownPeriodUpdated(uint256 newCooldownPeriod);
    event MinLiquidityForEpochProgressionUpdated(uint256 newMinLiquidity);
    event MinTokenLiquidityForEpochProgressionUpdated(
        uint256 newMinTokenLiquidity
    );

    event EpochFinalized(address indexed token, uint256 epoch, bool isETHPool);

    /// @notice Emitted when ETH is withdrawn in emergency
    event EmergencyWithdrawETH(address indexed recipient, uint256 amount);

    /// @notice Emitted when tokens are withdrawn in emergency
    event EmergencyWithdrawToken(
        address indexed token,
        address indexed recipient,
        uint256 amount
    );

    /**
     * @notice Add ETH liquidity to the pool
     * @param token Address of the token to provide ETH liquidity for
     */
    function addETHLiquidity(address token) external payable;

    /**
     * @notice Add token liquidity to the pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function addTokenLiquidity(address token, uint256 tokenAmount) external;

    /**
     * @notice Remove liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     * @param minTokenAmount Minimum amount of tokens to receive
     * @param currentETHEpoch Current ETH epoch
     * @param currentTokenEpoch Current token epoch
     */
    function removeLiquidity(
        address token,
        uint256 shares,
        uint256 minEthAmount,
        uint256 minTokenAmount,
        uint256 currentETHEpoch,
        uint256 currentTokenEpoch
    ) external;

    /**
     * @notice Remove ETH liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     * @param epoch Epoch to remove liquidity from
     */
    function removeETHLiquidity(
        address token,
        uint256 shares,
        uint256 minEthAmount,
        uint256 epoch
    ) external;

    /**
     * @notice Remove token liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minTokenAmount Minimum amount of tokens to receive
     * @param epoch Epoch to remove liquidity from
     */
    function removeTokenLiquidity(
        address token,
        uint256 shares,
        uint256 minTokenAmount,
        uint256 epoch
    ) external;

    /**
     * @notice Execute buy order - Orderbook sends ETH, receives tokens
     * @param token The token being bought
     * @param ethAmount Amount of ETH sent by orderbook
     * @param tokenAmount Amount of tokens to send to orderbook
     */
    function executeBuyOrder(
        address token,
        uint256 ethAmount,
        uint256 tokenAmount
    ) external payable;

    /**
     * @notice Execute sell order - Orderbook sends tokens, receives ETH
     * @param token The token being sold
     * @param ethAmount Amount of ETH to send to orderbook
     * @param tokenAmount Amount of tokens sent by orderbook
     */
    function executeSellOrder(
        address token,
        uint256 ethAmount,
        uint256 tokenAmount
    ) external;

    /**
     * @notice Distributes fee distribution from orderbook to be distributed to market makers
     * @param token Address of the token pool to distribute fees for
     * @param epoch Epoch to distribute fee.
     * @param isETHPool Whether to distribute to ETH pool (true) or token pool (false)
     */
    function distributePoolFee(
        address token,
        uint256 epoch,
        bool isETHPool
    ) external payable;

    /**
     * @notice Claim ETH rewards for ETH providers
     * @param token Address of the token pool to claim rewards from
     * @param epoch Epoch to claim rewards from
     */
    function claimEthPoolFee(address token, uint256 epoch) external;

    /**
     * @notice Claim token rewards for token providers
     * @param token Address of the token pool to claim rewards from
     * @param epoch Epoch to claim rewards from
     */
    function claimEthFeeFromTokenPool(address token, uint256 epoch) external;

    /**
     * @notice Get the current ETH epoch for a token
     * @param token Address of the token
     * @return Current ETH epoch number
     */
    function currentETHEpochs(address token) external view returns (uint256);

    /**
     * @notice Get the current token epoch for a token
     * @param token Address of the token
     * @return Current token epoch number
     */
    function currentTokenEpochs(address token) external view returns (uint256);

    /**
     * @notice Get the Uniswap V2 pair address for a given token
     * @param token Address of the token
     * @return pairAddress Address of the Uniswap V2 pair
     */
    function getPairAddress(
        address token
    ) external view returns (address pairAddress);

    /**
     * @notice Get the reserves for a token pair
     * @param token Address of the token
     * @return reserveETH ETH reserve amount
     * @return reserveToken Token reserve amount
     */
    function getReserves(
        address token
    ) external view returns (uint256 reserveETH, uint256 reserveToken);

    /**
     * @notice Set epoch cooldown period to prevent rapid epoch creation
     * @param _epochCooldownPeriod New cooldown period in seconds
     */
    function setEpochCooldownPeriod(uint256 _epochCooldownPeriod) external;

    /**
     * @notice Set minimum ETH liquidity required for epoch progression
     * @param _minLiquidityForEpochProgression New minimum ETH liquidity amount
     */
    function setMinLiquidityForEpochProgression(
        uint256 _minLiquidityForEpochProgression
    ) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IGradientMarketMakerPoolV2
 * @notice Interface for individual token market maker pool contracts
 * @dev Each pool is dedicated to one token, so token parameters are not needed
 * @dev Uses merkle tree for efficient bulk position updates after trades
 */
interface IGradientMarketMakerPoolV2 {
    // Events
    event ETHLiquidityDeposited(
        address indexed user,
        address token,
        uint256 ethAmount,
        uint256 lpSharesMinted
    );

    event TokenLiquidityDeposited(
        address indexed user,
        address token,
        uint256 tokenAmount,
        uint256 lpSharesMinted
    );

    event ETHLiquidityWithdrawn(
        address indexed user,
        address token,
        uint256 ethAmount,
        uint256 lpSharesBurned
    );

    event TokenLiquidityWithdrawn(
        address indexed user,
        address token,
        uint256 tokenAmount,
        uint256 lpSharesBurned
    );

    event PoolFeeDistributed(
        address indexed from,
        uint256 amount,
        address token
    );

    event FeeClaimed(address indexed user, uint256 amount, address token);

    event PoolBalanceUpdated(
        address indexed token,
        uint256 newTotalEth,
        uint256 newTotalTokens,
        uint256 newTotalETHLPShares,
        uint256 newTotalTokenLPShares
    );

    event MinLiquidityUpdated(uint256 newMinLiquidity);
    event MinTokenLiquidityUpdated(uint256 newMinTokenLiquidity);

    event MerkleRootUpdated(uint256 indexed version, bytes32 merkleRoot);
    event UserPositionUpdated(
        address indexed user,
        uint256 indexed version,
        uint256 newETHPosition,
        uint256 newTokenPosition
    );

    /**
     * @notice Add liquidity to the pool with optional position update
     * @param tokenAmount Amount of tokens to deposit
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function addLiquidityWithProof(
        uint256 tokenAmount,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external payable;

    /**
     * @notice Add ETH liquidity to the pool for a specific user
     * @param user User address to add liquidity for
     */
    function addETHLiquidityForUser(address user) external payable;

    /**
     * @notice Add token liquidity to the pool for a specific user
     * @param user User address to add liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function addTokenLiquidityForUser(
        address user,
        uint256 tokenAmount
    ) external;

    /**
     * @notice Add ETH liquidity to the pool with optional position update
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function addETHLiquidityWithProof(
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external payable;

    /**
     * @notice Add token liquidity to the pool with optional position update
     * @param tokenAmount Amount of tokens to deposit
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function addTokenLiquidityWithProof(
        uint256 tokenAmount,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Remove liquidity with position update
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     * @param minTokenAmount Minimum amount of tokens to receive
     * @param proof Merkle proof for position update
     * @param newETHPosition New ETH position (actual ETH amount)
     * @param newTokenPosition New token position (actual token amount)
     */
    function removeLiquidityWithUpdate(
        uint256 shares,
        uint256 minEthAmount,
        uint256 minTokenAmount,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Remove liquidity with optional position update
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     * @param minTokenAmount Minimum amount of tokens to receive
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function removeLiquidityWithProof(
        uint256 shares,
        uint256 minEthAmount,
        uint256 minTokenAmount,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Remove ETH liquidity with optional position update
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function removeETHLiquidityWithProof(
        uint256 shares,
        uint256 minEthAmount,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Remove token liquidity with optional position update
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minTokenAmount Minimum amount of tokens to receive
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function removeTokenLiquidityWithProof(
        uint256 shares,
        uint256 minTokenAmount,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Execute buy order - Orderbook sends ETH, receives tokens
     * @param ethAmount Amount of ETH sent by orderbook
     * @param tokenAmount Amount of tokens to send to orderbook
     * @param newMerkleRoot New merkle root to update after trade
     */
    function executeBuyOrder(
        uint256 ethAmount,
        uint256 tokenAmount,
        bytes32 newMerkleRoot
    ) external payable;

    /**
     * @notice Execute sell order - Orderbook sends tokens, receives ETH
     * @param ethAmount Amount of ETH to send to orderbook
     * @param tokenAmount Amount of tokens sent by orderbook
     * @param newMerkleRoot New merkle root to update after trade
     */
    function executeSellOrder(
        uint256 ethAmount,
        uint256 tokenAmount,
        bytes32 newMerkleRoot
    ) external;

    /**
     * @notice Distributes fee distribution from orderbook to be distributed to market makers
     */
    function distributePoolFee() external payable;

    /**
     * @notice Claim rewards with optional position update
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function claimRewardsWithProof(
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Claim only ETH rewards for ETH liquidity providers with optional position update
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function claimETHRewardsWithProof(
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Claim only ETH rewards for token liquidity providers with optional position update
     * @param proof Merkle proof for position update (required if user has pending updates)
     * @param newETHPosition New ETH position (required if proof provided)
     * @param newTokenPosition New token position (required if proof provided)
     */
    function claimTokenRewardsWithProof(
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Update Merkle root for LP share updates
     * @param version New version number
     * @param newMerkleRoot New Merkle root
     */
    function updateMerkleRoot(uint256 version, bytes32 newMerkleRoot) external;

    /**
     * @notice Set pending position update for automatic processing
     * @param user User address
     * @param proof Merkle proof
     * @param newETHPosition New ETH position (actual ETH amount)
     * @param newTokenPosition New token position (actual token amount)
     */
    function setPendingPositionUpdate(
        address user,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Set pending ETH provider position update for automatic processing
     * @param user User address
     * @param proof Merkle proof
     * @param newETHPosition New ETH position (actual ETH amount)
     */
    function setPendingETHProviderPositionUpdate(
        address user,
        bytes32[] calldata proof,
        uint256 newETHPosition
    ) external;

    /**
     * @notice Set pending token provider position update for automatic processing
     * @param user User address
     * @param proof Merkle proof
     * @param newTokenPosition New token position (actual token amount)
     */
    function setPendingTokenProviderPositionUpdate(
        address user,
        bytes32[] calldata proof,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Update user position using merkle proof
     * @param version Version of the merkle root
     * @param proof Merkle proof for the user's new position
     * @param newETHPosition New ETH position (actual ETH amount)
     * @param newTokenPosition New token position (actual token amount)
     */
    function updateUserPosition(
        uint256 version,
        bytes32[] calldata proof,
        uint256 newETHPosition,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Update only ETH provider position using merkle proof
     * @param version Version of the merkle root
     * @param proof Merkle proof for the user's new ETH position
     * @param newETHPosition New ETH position (actual ETH amount)
     */
    function updateETHProviderPosition(
        uint256 version,
        bytes32[] calldata proof,
        uint256 newETHPosition
    ) external;

    /**
     * @notice Update only token provider position using merkle proof
     * @param version Version of the merkle root
     * @param proof Merkle proof for the user's new token position
     * @param newTokenPosition New token position (actual token amount)
     */
    function updateTokenProviderPosition(
        uint256 version,
        bytes32[] calldata proof,
        uint256 newTokenPosition
    ) external;

    /**
     * @notice Get the Uniswap V2 pair address for this token
     * @return pairAddress Address of the Uniswap V2 pair
     */
    function getPairAddress() external view returns (address pairAddress);

    /**
     * @notice Get the reserves for this token pair
     * @return reserveETH ETH reserve amount
     * @return reserveToken Token reserve amount
     */
    function getReserves()
        external
        view
        returns (uint256 reserveETH, uint256 reserveToken);

    /**
     * @notice Set minimum ETH liquidity requirement
     * @param _minLiquidity New minimum ETH liquidity amount
     */
    function setMinLiquidity(uint256 _minLiquidity) external;

    /**
     * @notice Set minimum token liquidity requirement
     * @param _minTokenLiquidity New minimum token liquidity amount
     */
    function setMinTokenLiquidity(uint256 _minTokenLiquidity) external;

    /**
     * @notice Get user's total position in the pool
     * @param user Address of the user
     * @return ethPosition User's ETH position
     * @return tokenPosition User's token position
     * @return ethLPShares User's ETH LP shares
     * @return tokenLPShares User's token LP shares
     * @return pendingRewards User's pending rewards
     */
    function getUserPosition(
        address user
    )
        external
        view
        returns (
            uint256 ethPosition,
            uint256 tokenPosition,
            uint256 ethLPShares,
            uint256 tokenLPShares,
            uint256 pendingRewards
        );

    /**
     * @notice Get user's provider status
     * @param user Address of the user
     * @return ethProvider Whether user is ETH provider
     * @return tokenProvider Whether user is token provider
     */
    function getUserProviderStatus(
        address user
    ) external view returns (bool ethProvider, bool tokenProvider);

    // View functions for pool state
    function totalETH() external view returns (uint256);

    function totalTokens() external view returns (uint256);

    function totalETHLPShares() external view returns (uint256);

    function totalTokenLPShares() external view returns (uint256);

    function userETHPosition(address user) external view returns (uint256);

    function userTokenPosition(address user) external view returns (uint256);

    function userETHLPShares(address user) external view returns (uint256);

    function userTokenLPShares(address user) external view returns (uint256);

    // Merkle root view functions
    function merkleRoot() external view returns (bytes32);

    function currentVersion() external view returns (uint256);

    function versionMerkleRoots(
        uint256 version
    ) external view returns (bytes32);

    function userLastUpdateVersion(
        address user
    ) external view returns (uint256);

    // Provider status view functions
    function isETHProvider(address user) external view returns (bool);

    function isTokenProvider(address user) external view returns (bool);
}

